<?php
declare(strict_types=1); require dirname(__DIR__) . '/app/core/bootstrap.php'; require_role('technician'); $user=current_user(); $maintenanceId=filter_input(INPUT_GET,'maintenance_id',FILTER_VALIDATE_INT); $statement=$pdo->prepare('SELECT id FROM maintenance WHERE id=:id AND technician_id=:technician_id'); $statement->execute(['id'=>$maintenanceId,'technician_id'=>$user['id']]); if(!$statement->fetch()){http_response_code(404);exit('Maintenance not found.');} $errors=[]; if($_SERVER['REQUEST_METHOD']==='POST'){if(!verify_csrf_token($_POST['csrf_token']??null)||post_text('task_name')==='')$errors[]='Task name and valid form token are required.'; if(!valid_enum(post_text('status'),['pending','completed','not_completed']))$errors[]='Invalid task status.'; if(!$errors){(new MaintenanceTask($pdo))->create((int)$maintenanceId,post_text('task_name'),post_text('description'),post_text('status'));flash('message','Task added.');redirect('maintenance_task.php?maintenance_id='.$maintenanceId);}} $tasks=(new MaintenanceTask($pdo))->forMaintenance((int)$maintenanceId); require dirname(__DIR__).'/app/views/layout.php'; page_header('Maintenance tasks'); ?><h1>Maintenance tasks</h1><?php if($message=flash('message')):?><p class="message"><?=e($message)?></p><?php endif;?><?php foreach($errors as $error):?><p class="error"><?=e($error)?></p><?php endforeach;?><section class="panel"><form method="post"><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><label>Task name</label><input name="task_name" maxlength="200" required><label>Description</label><textarea name="description"></textarea><label>Status</label><select name="status"><option>pending</option><option>completed</option><option>not_completed</option></select><button type="submit">Add task</button></form></section><section class="panel"><ul><?php foreach($tasks as $task):?><li><?=e($task['task_name'])?>: <?=e($task['status'])?></li><?php endforeach;?></ul></section><?php page_footer(); ?>